/**
 * @name Server-Side Request Forgery (SSRF)
 * @description User-controlled URLs used in HTTP requests without validation can lead to SSRF
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf-requests
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "patch", "head", "options", "request"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF: HTTP request to URL from $@.", source.getNode(), "user-controlled source"

/**
 * @name Path traversal from user input to file operations
 * @description User-controlled file paths can lead to unauthorized file access
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-taint
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function parameters that could be user-controlled
    source instanceof DataFlow::ParameterNode or
    // Attribute access that might be user-controlled
    exists(DataFlow::AttrRead attr | source = attr)
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa | sink = fa.getAPathArgument())
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled input"

/**
 * @name HTTP Header Injection
 * @description User input flowing into HTTP headers without proper validation
 * @kind path-problem
 * @problem.severity error
 * @id py/http-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Setting headers
      call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "patch", "request"]).getACall() and
      sink = call.getArgByName("headers")
    )
    or
    exists(DataFlow::AttrWrite write |
      write.getAttributeName() in ["headers", "header"] and
      sink = write.getValue()
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential HTTP header injection from $@.", source.getNode(), "user input"
